		public static extern bool MagSetWindowTransform(IntPtr hwnd, ref Transformation pTransform);

		[DllImport("Magnification.dll", CallingConvention = CallingConvention.StdCall)]
		[return: MarshalAs(UnmanagedType.Bool)]
