                private void SetOverlaysVisible(bool visible)
                {
                        foreach (var ov in overlays)
                        {
                                ov.Visible = visible;
                        }
                        UpdateCursorVisibility(visible);
                }

                private void UpdateCursorVisibility(bool overlaysVisible)
                {
                        if (!overlaysVisible || overlays.Count == 0)
                        {
                                ShowSystemCursor();
                                return;
                        }
                        if (useMagnifiedCursor)
                                HideSystemCursor();
                        else
                                ShowSystemCursor();
                        if (forceSoftwareCursor)
                                ShowSystemCursor();
                }

                private void HideSystemCursor()
                {
                        if (isCursorHidden)
                                return;
                        Cursor.Hide();
                        isCursorHidden = true;
                }

                private void ShowSystemCursor()
                {
                        if (!isCursorHidden)
                                return;
                        Cursor.Show();
                        isCursorHidden = false;
                }

                private void ApplySoftwareCursorSetting()
                {
                        if (!forceSoftwareCursor)
                        {
                                RestoreSoftwareCursorSetting();
                                return;
                        }
                        if (!hasSavedMouseTrails)
                        {
                                uint value = 0;
                                if (NativeMethods.SystemParametersInfo((uint)SystemParametersInfoAction.SPI_GETMOUSETRAILS, 0, ref value, 0))
                                {
                                        savedMouseTrails = value;
                                        hasSavedMouseTrails = true;
                                }
                        }
                        uint trails = 2;
                        NativeMethods.SystemParametersInfo((uint)SystemParametersInfoAction.SPI_SETMOUSETRAILS, trails, ref trails,
                                (uint)SystemParametersInfoFlags.SPIF_UPDATEINIFILE | (uint)SystemParametersInfoFlags.SPIF_SENDCHANGE);
                }

                private void RestoreSoftwareCursorSetting()
                {
                        if (!hasSavedMouseTrails)
                                return;
                        uint trails = savedMouseTrails;
                        NativeMethods.SystemParametersInfo((uint)SystemParametersInfoAction.SPI_SETMOUSETRAILS, trails, ref trails,
                                (uint)SystemParametersInfoFlags.SPIF_UPDATEINIFILE | (uint)SystemParametersInfoFlags.SPIF_SENDCHANGE);
                        hasSavedMouseTrails = false;
                }

                private void ApplyCursorSchemeSetting()
                {
                        if (!forceSoftwareCursor || !normalizeCursorScheme)
                        {
                                RestoreCursorSchemeSetting();
                                return;
                        }
                        if (savedCursorValues == null)
                        {
                                savedCursorValues = LoadCurrentCursorValues();
                        }
                        if (!ApplyCursorScheme("Windows Black"))
                        {
                                ApplyCursorScheme("Windows Black (system scheme)");
                        }
                }

                private void RestoreCursorSchemeSetting()
                {
                        if (savedCursorValues == null)
                                return;
                        try
                        {
                                using (RegistryKey cursors = Registry.CurrentUser.OpenSubKey("Control Panel\\Cursors", true))
                                {
                                        if (cursors != null)
                                        {
                                                foreach (var kvp in savedCursorValues)
                                                {
                                                        cursors.SetValue(kvp.Key, kvp.Value, RegistryValueKind.String);
                                                }
                                        }
                                }
                                uint dummy = 0;
                                NativeMethods.SystemParametersInfo((uint)SystemParametersInfoAction.SPI_SETCURSORS, 0, ref dummy,
                                        (uint)SystemParametersInfoFlags.SPIF_UPDATEINIFILE | (uint)SystemParametersInfoFlags.SPIF_SENDCHANGE);
                        }
                        catch
                        {
                                // best-effort restore
                        }
                        savedCursorValues = null;
                }

                private Dictionary<string, string> LoadCurrentCursorValues()
                {
                        var values = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
                        try
                        {
                                using (RegistryKey cursors = Registry.CurrentUser.OpenSubKey("Control Panel\\Cursors", false))
                                {
                                        if (cursors != null)
                                        {
                                                foreach (string name in CursorValueNames())
                                                {
                                                        string value = cursors.GetValue(name, "") as string;
                                                        values[name] = value ?? "";
                                                }
                                        }
                                }
                        }
                        catch
                        {
                        }
                        return values;
                }

                private bool ApplyCursorScheme(string schemeName)
                {
                        try
                        {
                                using (RegistryKey schemes = Registry.CurrentUser.OpenSubKey("Control Panel\\Cursors\\Schemes", false))
                                using (RegistryKey cursors = Registry.CurrentUser.OpenSubKey("Control Panel\\Cursors", true))
                                {
                                        if (schemes == null || cursors == null)
                                                return false;
                                        string scheme = schemes.GetValue(schemeName, "") as string;
                                        if (string.IsNullOrEmpty(scheme))
                                                return false;
                                        string[] parts = scheme.Split(new[] { ',' }, StringSplitOptions.None);
                                        string[] names = CursorValueNames();
                                        int count = Math.Min(parts.Length, names.Length);
                                        for (int i = 0; i < count; i++)
                                        {
                                                cursors.SetValue(names[i], parts[i], RegistryValueKind.String);
                                        }
                                }
                                uint dummy = 0;
                                NativeMethods.SystemParametersInfo((uint)SystemParametersInfoAction.SPI_SETCURSORS, 0, ref dummy,
                                        (uint)SystemParametersInfoFlags.SPIF_UPDATEINIFILE | (uint)SystemParametersInfoFlags.SPIF_SENDCHANGE);
                                return true;
                        }
                        catch
                        {
                                // best-effort apply
                        }
                        return false;
                }

                private string[] CursorValueNames()
                {
                        return new[]
                        {
                                "Arrow",
                                "Help",
                                "AppStarting",
                                "Wait",
                                "Crosshair",
                                "IBeam",
                                "NWPen",
                                "No",
                                "SizeNS",
                                "SizeWE",
                                "SizeNWSE",
                                "SizeNESW",
                                "SizeAll",
                                "UpArrow",
                                "Hand"
                        };
                }

		private bool IsCursorOnOverlay()
		{
			if (overlays.Count == 0)
				return false;
			Point pos = Cursor.Position;
			for (int i = 0; i < overlays.Count; i++)
			{
				if (overlays[i].Visible && overlays[i].Bounds.Contains(pos))
					return true;
			}
			return false;
		}

		protected override void WndProc(ref Message m)
		{
			// Listen for operating system messages.
			switch (m.Msg)
			{
				case (int)WindowMessage.WM_DWMCOMPOSITIONCHANGED:
					//aero has been enabled/disabled. It causes the magnified control to stop working
					if (Environment.OSVersion.Version.Major == 6 && Environment.OSVersion.Version.Minor == 0)
					{
						//running Vista.
						//The creation of the magnification Window on this OS seems to change desktop composition,
						//leading to infinite loop
					}
					else
					{
						Initialization();
					}
					break;
				case (int)WindowMessage.WM_HOTKEY:
					switch ((int)m.WParam)
					{
						case HALT_HOTKEY_ID:
							//otherwise, if paused, the application never stops
							Shutdown(true);
							break;
						case TOGGLE_HOTKEY_ID:
							this.mainLoopPaused = !mainLoopPaused;
							break;
						case RESET_TIMER_HOTKEY_ID:
							this.refreshInterval = DEFAULT_SLEEP_TIME;
							break;
						case INCREASE_TIMER_HOTKEY_ID:
							this.refreshInterval += DEFAULT_INCREASE_STEP;
							break;
						case DECREASE_TIMER_HOTKEY_ID:
							this.refreshInterval -= DEFAULT_INCREASE_STEP;
							if (this.refreshInterval < 0)
							{
								this.refreshInterval = 0;
							}
							break;
						case MODE1_HOTKEY_ID:
							BuiltinMatrices.ChangeColorEffect(overlays, BuiltinMatrices.Negative);
							break;
						case MODE2_HOTKEY_ID:
							BuiltinMatrices.ChangeColorEffect(overlays, BuiltinMatrices.NegativeHueShift180);
							break;
						case MODE3_HOTKEY_ID:
							BuiltinMatrices.ChangeColorEffect(overlays, BuiltinMatrices.NegativeHueShift180Variation1);
							break;
						case MODE4_HOTKEY_ID:
							BuiltinMatrices.ChangeColorEffect(overlays, BuiltinMatrices.NegativeHueShift180Variation2);
							break;
						case MODE5_HOTKEY_ID:
							BuiltinMatrices.ChangeColorEffect(overlays, BuiltinMatrices.NegativeHueShift180Variation3);
							break;
						case MODE6_HOTKEY_ID:
							BuiltinMatrices.ChangeColorEffect(overlays, BuiltinMatrices.NegativeHueShift180Variation4);
							break;
						case MODE7_HOTKEY_ID:
							BuiltinMatrices.ChangeColorEffect(overlays, BuiltinMatrices.NegativeSepia);
							break;
						case MODE8_HOTKEY_ID:
							BuiltinMatrices.ChangeColorEffect(overlays, BuiltinMatrices.NegativeGrayScale);
							break;
						case MODE9_HOTKEY_ID:
							BuiltinMatrices.ChangeColorEffect(overlays, BuiltinMatrices.NegativeRed);
							break;
						case MODE10_HOTKEY_ID:
							BuiltinMatrices.ChangeColorEffect(overlays, BuiltinMatrices.Red);
							break;
						default:
							break;
					}
					break;
			}
			base.WndProc(ref m);
		}

		internal void Shutdown(bool exitApplication)
		{
			if (isShuttingDown)
				return;
			isShuttingDown = true;
			mainLoopPaused = false;
			RestoreSoftwareCursorSetting();
			RestoreCursorSchemeSetting();
			try
			{
				SetOverlaysVisible(false);
			}
			catch
			{
				// best-effort during shutdown
			}
			if (notifyIcon != null)
			{
				try
				{
					notifyIcon.Visible = false;
				}
				catch
				{
				}
				try
				{
					notifyIcon.Dispose();
				}
				catch
				{
				}
			}
			try
			{
				this.Close();
			}
			catch
			{
			}
			try
			{
				this.Dispose();
			}
			catch
			{
			}
			if (exitApplication)
				Application.Exit();
		}

                protected override void Dispose(bool disposing)
                {
                        isShuttingDown = true;
                        UnregisterHotKeys();
                        if (displaySettingsHandler != null)
                                Microsoft.Win32.SystemEvents.DisplaySettingsChanged -= displaySettingsHandler;
                        foreach (var ov in overlays)
                                ov.Dispose();
                        overlays.Clear();
                        UpdateCursorVisibility(false);
                        RestoreSoftwareCursorSetting();
                        RestoreCursorSchemeSetting();
                        NativeMethods.MagUninitialize();
                        base.Dispose(disposing);
                }

                internal static string GetMonitorDetail(Screen screen)
                {
                        int index = Array.IndexOf(Screen.AllScreens, screen) + 1;
                        Config cfg = Settings.Load();
                        string id = Settings.GetMonitorId(screen);
                        string alias = null;
                        if (cfg.MonitorLabels != null)
                        {
                                foreach (var ml in cfg.MonitorLabels)
                                {
                                        if ((!string.IsNullOrEmpty(ml.Id) && ml.Id == id) || ml.Device == screen.DeviceName)
                                        {
                                                alias = ml.Label;
                                                break;
                                        }
                                }
                        }
                        string name = alias;
                        if (string.IsNullOrEmpty(name))
                        {
                                NativeMethods.DISPLAY_DEVICE device = new NativeMethods.DISPLAY_DEVICE();
                                device.cb = Marshal.SizeOf(typeof(NativeMethods.DISPLAY_DEVICE));
                                if (NativeMethods.EnumDisplayDevices(screen.DeviceName, 0, ref device, 0))
                                {
                                        if (!string.IsNullOrEmpty(device.DeviceString))
                                                name = device.DeviceString.Trim();
                                }
                        }
                        if (string.IsNullOrEmpty(name))
                                name = screen.DeviceName;
                        return $"Display {index} - {name} [{id}] ({screen.Bounds.Width}x{screen.Bounds.Height})";
                }

                internal static string GetMonitorName(Screen screen)
                {
                        NativeMethods.DISPLAY_DEVICE device = new NativeMethods.DISPLAY_DEVICE();
                        device.cb = Marshal.SizeOf(typeof(NativeMethods.DISPLAY_DEVICE));
                        if (NativeMethods.EnumDisplayDevices(screen.DeviceName, 0, ref device, 0))
                        {
                                if (!string.IsNullOrEmpty(device.DeviceString))
                                {
                                        return device.DeviceString.Trim();
                                }
                        }
                        return screen.DeviceName;
                }

	}
}

